import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals } from '../src/invoices.js';

test('createInvoice creates a draft invoice with product details', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;
  assert.equal(invoice.customerId, 'C-001');
  assert.equal(invoice.issueDate, '2025-01-15');
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.lines.length, 2);

  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
  assert.equal(invoice.lines[0].name, 'Design work (hour)');
  assert.equal(invoice.lines[0].qty, 5);
  assert.equal(invoice.lines[0].unitPrice, 8500);
  assert.equal(invoice.lines[0].vatRate, 21);

  assert.equal(invoice.lines[1].sku, 'DEV-HOUR');
  assert.equal(invoice.lines[1].name, 'Development (hour)');
  assert.equal(invoice.lines[1].qty, 10);
  assert.equal(invoice.lines[1].unitPrice, 9500);
  assert.equal(invoice.lines[1].vatRate, 21);
});

test('createInvoice rejects an unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects invalid date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025/01/15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects invalid calendar dates', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects missing date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects empty lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-01-15',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects non-array lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-01-15',
      lines: null,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-01-15',
      lines: [{ sku: 'DES-HOUR', qty: -1 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects non-integer quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-01-15',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice with VAT-exempt product', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 2 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 0);
});

test('createInvoice with mixed VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-03-01',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  const linesCopy = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines,
  });

  assert.deepEqual(lines, linesCopy);
});

test('lineTotal calculates qty × unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
});

test('lineTotal with qty 1', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
});

test('lineTotal with large numbers', () => {
  assert.equal(lineTotal({ qty: 100, unitPrice: 245000 }), 24500000);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.total, 42500);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500 + 95000);
  assert.equal(totals.total, 137500);
});

test('invoiceTotals with three lines', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2025-03-01',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 8500, vatRate: 21 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 25500 + 3700 + 120000);
  assert.equal(totals.total, 149200);
});

test('invoiceTotals with empty lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals from actual createInvoice result', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

